from summarize import summarize


def test_basic():
    rows = [
        {'region': 'NA', 'revenue': 100},
        {'region': 'EU', 'revenue': 200},
        {'region': 'NA', 'revenue': 50},
    ]
    assert summarize(rows) == {'NA': 150.0, 'EU': 200.0}


def test_numeric_strings():
    rows = [
        {'region': 'AP', 'revenue': '30.5'},
        {'region': 'AP', 'revenue': '19.5'},
    ]
    assert summarize(rows) == {'AP': 50.0}


def test_missing_revenue():
    rows = [
        {'region': 'NA', 'revenue': None},
        {'region': 'EU', 'revenue': 100},
    ]
    assert summarize(rows) == {'EU': 100.0}


def test_unparseable_revenue():
    rows = [
        {'region': 'NA', 'revenue': 'foo'},
        {'region': 'EU', 'revenue': 100},
    ]
    assert summarize(rows) == {'EU': 100.0}


def test_missing_region():
    rows = [
        {'region': None, 'revenue': 100},
        {'region': 'EU', 'revenue': 200},
    ]
    assert summarize(rows) == {'EU': 200.0}


def test_empty_input():
    assert summarize([]) == {}


def test_all_invalid():
    rows = [
        {'region': 'NA', 'revenue': None},
        {'region': None, 'revenue': 100},
        {'region': 'EU', 'revenue': 'bad'},
    ]
    assert summarize(rows) == {}


def test_negative_revenue():
    rows = [
        {'region': 'NA', 'revenue': -10},
        {'region': 'NA', 'revenue': 5},
    ]
    assert summarize(rows) == {'NA': -5.0}

